from dataclasses import dataclass, field
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
from typing import Dict, List, Optional

class WishlistError(Exception):
    pass

class DuplicateItemError(WishlistError):
    pass

class WishlistFullError(WishlistError):
    pass

class ItemNotFoundError(WishlistError):
    pass

class InvalidPriceError(WishlistError):
    pass

@dataclass(frozen=True)
class WishlistItem:
    product_id: str
    added_at: datetime
    price_at_add: Decimal

@dataclass(frozen=True)
class PriceDrop:
    product_id: str
    old_price: Decimal
    new_price: Decimal
    drop_pct: Decimal

class WishlistService:
    def __init__(self, max_items: int = 50) -> None:
        if max_items < 1:
            raise ValueError("max_items must be greater than 0")
        self.max_items = max_items
        self.wishlists: Dict[str, List[WishlistItem]] = {}

    def add_item(self, customer_id: str, product_id: str, price: Decimal, now: datetime) -> WishlistItem:
        if not customer_id.strip() or not product_id.strip():
            raise ValueError("customer_id and product_id must not be empty or contain only spaces")
        if price <= 0:
            raise InvalidPriceError("price must be greater than 0")
        if customer_id not in self.wishlists:
            self.wishlists[customer_id] = []
        if any(item.product_id == product_id for item in self.wishlists[customer_id]):
            raise DuplicateItemError("product already in wishlist")
        if len(self.wishlists[customer_id]) >= self.max_items:
            raise WishlistFullError("wishlist is full")
        item = WishlistItem(product_id, now, price)
        self.wishlists[customer_id].append(item)
        return item

    def remove_item(self, customer_id: str, product_id: str) -> None:
        if customer_id not in self.wishlists:
            raise ItemNotFoundError("product not found in wishlist")
        if product_id not in (item.product_id for item in self.wishlists[customer_id]):
            raise ItemNotFoundError("product not found in wishlist")
        self.wishlists[customer_id] = [item for item in self.wishlists[customer_id] if item.product_id != product_id]

    def list_items(self, customer_id: str) -> List[WishlistItem]:
        return self.wishlists.get(customer_id, [])

def detect_price_drops(items: List[WishlistItem], current_prices: Dict[str, Decimal], min_drop_pct: Decimal) -> List[PriceDrop]:
    if min_drop_pct <= 0 or min_drop_pct > 100:
        raise ValueError("min_drop_pct must be between 0 and 100")
    price_drops = []
    for item in items:
        if item.product_id in current_prices:
            new_price = current_prices[item.product_id]
            drop_pct = round((item.price_at_add - new_price) / item.price_at_add * 100, 2, ROUND_HALF_UP)
            if drop_pct >= min_drop_pct:
                price_drops.append(PriceDrop(item.product_id, item.price_at_add, new_price, drop_pct))
    price_drops.sort(key=lambda x: (-x.drop_pct, x.product_id))
    return price_drops
